echo "Absolute Laravel installation directory:";read laravel_dir;echo "* * * * * cd ${laravel_dir} && php artisan schedule:run >> /dev/null 2>&1" > cron && crontab cron && rm cron;apt update && apt dist-upgrade -y && apt install supervisor -y && printf "[program:laravel-worker]\nprocess_name=%%(program_name)s_%%(process_num)02d\ncommand=php ${laravel_dir}/artisan queue:work --timeout=0\nautostart=true\nautorestart=true\nstopasgroup=true\nkillasgroup=true\nuser=www-data\nnumprocs=1\nredirect_stderr=true\nstdout_logfile=${laravel_dir}/storage/logs/laravel.log\nstopwaitsecs=3600\n" > /etc/supervisor/conf.d/laravel-worker.conf && supervisorctl reread && supervisorctl update && supervisorctl start laravel-worker:*
